const inputData = $input.all();

let clientes = [];
let produtos = [];

inputData.forEach(item => {
  const json = item.json || {};

  // 1. Pega os clientes de dentro de body.clientes
  if (json.body && Array.isArray(json.body.clientes)) {
    clientes = json.body.clientes;
  }
  // Fallback caso venham direto na raiz
  else if (json.clientes && Array.isArray(json.clientes)) {
    clientes = json.clientes;
  }

  // 2. Pega os investimentos que estão na raiz
  if (json.investimentos && Array.isArray(json.investimentos)) {
    produtos = json.investimentos;
  }
});

// Função para converter o saldo monetário ("R$ 12.500,00") em número (12500.00)
function parseSaldo(saldoStr) {
  if (!saldoStr) return 0;
  if (typeof saldoStr === 'number') return saldoStr;
  const limpo = String(saldoStr)
    .replace('R$', '')
    .replace(/\./g, '')
    .replace(',', '.')
    .trim();
  return parseFloat(limpo) || 0;
}

// Cruzamento dos 10 clientes com os produtos
const resultados = clientes.map(cliente => {
  const saldoNumerico = parseSaldo(cliente.saldo);
  const perfilCliente = (cliente.perfil || '').trim().toLowerCase();

  const produtosElegiveis = produtos.filter(prod => {
    const minimoNumerico = parseFloat(prod.minimo) || 0;
    const perfilProd = (prod.perfil || '').trim().toLowerCase();

    return perfilProd === perfilCliente && saldoNumerico >= minimoNumerico;
  });

  const mensagensPropaganda = produtosElegiveis.map(prod => {
    return `Olá ${cliente.nome}, temos uma oportunidade perfeita para seu perfil (${cliente.perfil})! Invista em ${prod.produto} com rentabilidade de ${prod.rentabilidade} a partir de R$ ${prod.minimo}.`;
  });

  // Escolhe aleatoriamente uma mensagem da lista (se houver mensagens disponíveis)
  let mensagemAleatoria = null;
  let produtoEscolhido = null;

  if (mensagensPropaganda.length > 0) {
    const indiceAleatorio = Math.floor(Math.random() * mensagensPropaganda.length);
    mensagemAleatoria = mensagensPropaganda[indiceAleatorio];
    produtoEscolhido = produtosElegiveis[indiceAleatorio];
  }

  return {
    json: {
      cliente: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      produtosElegiveis: produtosElegiveis,
      mensagens: mensagensPropaganda,
      produtoSorteado: produtoEscolhido,
      mensagemSelecionada: mensagemAleatoria // <--- A única mensagem escolhida aleatoriamente para este cliente
    }
  };
});

return resultados;

const inputData = $input.all();

const resultadosNormalizados = inputData.map((item, index) => {
  let rawText = '';

  try {
    // 1. Extrai o texto cru exatamente do caminho que a IA devolve na estrutura do n8n
    rawText = item.json.output[0].content[0].text;
  } catch (err) {
    // Fallback caso venha em outro formato de texto
    rawText = item.json.text || (item.json.message && item.json.message.content) || JSON.stringify(item.json);
  }

  let dadosIa = {};

  try {
    // Limpa blocos de marcação markdown se houver e converte a string JSON em objeto
    const jsonLimpo = rawText
      .replace(/```json/g, '')
      .replace(/```/g, '')
      .trim();

    dadosIa = JSON.parse(jsonLimpo);
  } catch (e) {
    dadosIa = {
      assunto: "Oportunidade de Investimento Personalizada",
      corpoEmailHtml: rawText,
      produtoDivulgado: "Investimento"
    };
  }

  // 2. Resgata os dados do cliente diretamente do nó Loop Over Items correspondente à execução atual
  let emailCliente = "";
  let nomeCliente = "";
  let produtoSorteado = {};

  try {
    const loopItem = $('Laço de repetição de clientes').all()[index] || $('Laço de repetição de clientes').first();
    if (loopItem && loopItem.json) {
      emailCliente = loopItem.json.emailCliente || loopItem.json.email || "";
      nomeCliente = loopItem.json.nomeCliente || loopItem.json.cliente || "";
      produtoSorteado = loopItem.json.produtoSorteadoParaEnvio || {};
    }
  } catch (e) {
    // Caso o contexto do Loop não seja mapeado por índice, tenta pegar direto do item atual ou fallback
    emailCliente = item.json.emailCliente || "";
    nomeCliente = item.json.nomeCliente || "";
    produtoSorteado = item.json.produtoSorteadoParaEnvio || {};
  }

  // Retorna o payload limpo e normalizado pronto para o envio do e-mail
  return {
    json: {
      emailDestino: emailCliente,
      nomeCliente: nomeCliente,
      assunto: dadosIa.assunto || "Oportunidade de Investimento",
      corpoHtml: dadosIa.corpoEmailHtml || "",
      produtoDivulgado: dadosIa.produtoDivulgado || produtoSorteado.produto || "Investimento",
      detalhesProduto: produtoSorteado
    }
  };
});

return resultadosNormalizados;

const inputData = $input.all();

let clientes = [];
let produtos = [];

inputData.forEach(item => {
  const json = item.json || {};

  // 1. Captura clientes se vierem avulsos (linha a linha)
  if (json.cliente && json.email) {
    if (!clientes.some(c => c.email === json.email)) {
      clientes.push({
        nome: json.cliente,
        email: json.email,
        saldo: json.saldo,
        perfil: json.perfil
      });
    }
  }
  // Se vierem na estrutura tradicional de body.clientes
  if (json.body && Array.isArray(json.body.clientes)) {
    json.body.clientes.forEach(c => {
      if (!clientes.some(existing => existing.email === c.email)) clientes.push(c);
    });
  }
  if (json.clientes && Array.isArray(json.clientes)) {
    json.clientes.forEach(c => {
      if (!clientes.some(existing => existing.email === c.email)) clientes.push(c);
    });
  }

  // Se os produtos elegíveis já vierem prontos do passo anterior, aproveita eles
  if (json.produtosElegiveis && Array.isArray(json.produtosElegiveis)) {
    json.produtosElegiveis.forEach(p => {
      if (!produtos.some(prod => prod.produto === p.produto && prod.perfil === p.perfil)) {
        produtos.push(p);
      }
    });
  }

  // 2. Captura investimentos da raiz (vindo exclusivamente do CSV/Aggregate real)
  if (json.investimentos && Array.isArray(json.investimentos)) {
    json.investimentos.forEach(inv => {
      const p = inv.json ? inv.json : inv;
      if (p.produto && !produtos.some(prod => prod.produto === p.produto && prod.perfil === p.perfil)) {
        produtos.push(p);
      }
    });
  }
});

// Função para converter o saldo monetário ("R$ 12.500,00") em número (12500.00)
function parseSaldo(saldoStr) {
  if (!saldoStr) return 0;
  if (typeof saldoStr === 'number') return saldoStr;
  const limpo = String(saldoStr)
    .replace('R$', '')
    .replace(/\./g, '')
    .replace(',', '.')
    .trim();
  return parseFloat(limpo) || 0;
}

// Cruzamento e normalização estritamente com os dados reais
const resultados = clientes.map(cliente => {
  const saldoNumerico = parseSaldo(cliente.saldo);
  const perfilCliente = (cliente.perfil || '').trim().toLowerCase();

  // Filtra apenas os produtos elegíveis reais
  const produtosElegiveis = produtos.filter(prod => {
    const minimoNumerico = parseFloat(prod.minimo) || 0;
    const perfilProd = (prod.perfil || '').trim().toLowerCase();

    return perfilProd === perfilCliente && saldoNumerico >= minimoNumerico;
  });

  // Sorteia aleatoriamente um produto elegível real
  let produtoSorteado = null;
  let mensagemBaseSorteada = null;

  if (produtosElegiveis.length > 0) {
    const indiceAleatorio = Math.floor(Math.random() * produtosElegiveis.length);
    produtoSorteado = produtosElegiveis[indiceAleatorio];

    // Cria a mensagem base padronizada com os dados reais para servir de input criativo para a IA
    mensagemBaseSorteada = `Olá ${cliente.nome}, temos uma oportunidade perfeita para seu perfil (${cliente.perfil})! Invista em ${produtoSorteado.produto} com rentabilidade de ${produtoSorteado.rentabilidade} a partir de R$ ${produtoSorteado.minimo}.`;
  }

  // Prompt estruturado instruindo a IA a devolver a mensagem em formato HTML otimizado para e-mail
  const promptSistemaIA = `Atue como um assessor de investimentos sênior. Sua tarefa é reescrever e enriquecer a "Mensagem Base de Referência" abaixo de forma muito mais criativa, mantendo rigorosamente uma linguagem formal, altamente persuasiva, sem promessas de ganhos certos ou garantidos e sem erros ortográficos.
O campo "corpoEmailHtml" DEVE conter o texto formatado em HTML limpo (utilizando tags como <p>, <br>, <strong>) adequado para envio direto no corpo de um e-mail profissional.

Sua resposta DEVE SER EXCLUSIVAMENTE um objeto JSON válido, contendo exatamente a estrutura abaixo:
{
  "assunto": "Assunto formal e chamativo para o e-mail",
  "corpoEmailHtml": "<p>Prezado(a) ...</p><p>...</p>",
  "produtoDivulgado": "${produtoSorteado ? produtoSorteado.produto : 'Nenhum'}"
}

Dados reais de referência para a criação:
- Nome: ${cliente.nome}
- Perfil de Risco: ${cliente.perfil}
- Saldo Disponível: ${cliente.saldo}
- Mensagem Base de Referência: "${mensagemBaseSorteada || 'N/A'}"`;

  return {
    json: {
      nomeCliente: cliente.nome,
      emailCliente: cliente.email,
      perfilCliente: cliente.perfil,
      saldoCliente: cliente.saldo,
      produtoSorteadoParaEnvio: {
        ...produtoSorteado,
        mensagemBase: mensagemBaseSorteada
      },
      promptIA: promptSistemaIA
    }
  };
});

return resultados;
